pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0);
        address owner = c.owner();
        vm.deal(address(c), amount);
        address reverter = address(new Reverter());
        vm.prank(owner);
        bool ok = true;
        try c.withdraw(amount) { ok = false; } catch { ok = true; }
        assertTrue(ok);
    }
}
contract Reverter { fallback() external payable { revert(); } }
